import type { AssistStatusKey } from "@/lib/key-value-pairs/key-value-pair-types";

/**
 * Type: Response
 * Description: Represents a single day attendance record of a student in an
 * academic cycle enrollment. Attendance is recorded per day, not per subject.
 */
export interface StudentAssistResponse {
    /**
     * Unique identifier for the attendance record, generated by backend
     */
    id: string;
    /**
     * Identifier of the academic cycle enrollment the record belongs to
     */
    academicCycleEnrollmentId: string;
    /**
     * Day the attendance was recorded (ISO date)
     */
    assistDate: string;
    /**
     * Whether the student attended classes that day
     */
    status: AssistStatusKey;
    /**
     * Free-text reason of absence, only when the student did not attend
     */
    absenceReason: string | null;
}